import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { Plus, Save, Trash2, RefreshCw, Power, PowerOff, Play, LockKeyhole, Trophy, RotateCcw } from 'lucide-react'
import { PageHeader } from '../../components/layout/PageHeader'
import { StatusBadge } from '../../components/status/StatusBadge'
import { Button } from '../../lib/shadcn/button'
import { toast } from '../../lib/shadcn/sonner'
import { supabase } from '../../lib/supabase'

const inputCls = 'h-9 w-full rounded-md border border-border bg-background px-2.5 text-sm outline-none focus:ring-1 focus:ring-ring'
const areaCls = 'min-h-20 w-full rounded-md border border-border bg-background px-2.5 py-2 text-sm outline-none focus:ring-1 focus:ring-ring'

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground"><span>{label}</span>{children}</label>
}
function Section({ title, children, actions }: { title: string; children: React.ReactNode; actions?: React.ReactNode }) {
  return <section className="rounded-lg border border-border bg-card p-density-lg shadow-retool-sm"><div className="mb-density-md flex items-center justify-between gap-3"><h2 className="text-base font-semibold">{title}</h2>{actions}</div>{children}</section>
}
function JsonField({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  return <textarea className={areaCls} value={value} onChange={(e) => onChange(e.target.value)} placeholder="{}" />
}
function parseJson(s: string) { try { return s.trim() ? JSON.parse(s) : {} } catch { throw new Error('JSON must be valid.') } }
function fmt(v: string | null | undefined) { return v ? new Date(v).toLocaleString() : '—' }
function errText(e: unknown) { return e instanceof Error ? e.message : 'Operation failed' }

export function BonusesPage() {
  const [rows, setRows] = useState<any[]>([]); const [partners, setPartners] = useState<any[]>([]); const [features, setFeatures] = useState<any[]>([])
  const [editing, setEditing] = useState<any | null>(null); const [showForm, setShowForm] = useState(false); const [loading, setLoading] = useState(true)
  const blank = () => ({ partner_id:'', title:'', slug:'', description:'', bonus_type:'other', delivery_type:'code', code:'', affiliate_url:'', image_url:'', offer_value:'', terms:'', starts_at:'', expires_at:'', status:'draft', featured:false, sort_order:0, max_claims:'', brand_name:'Unknown Brand', brand_logo_url:'', bonus_access_type:'public' })
  const [form, setForm] = useState<any>(blank())
  async function load() { setLoading(true); try { const [{ data: b, error: be }, { data: p, error: pe }, { data: f, error: fe }] = await Promise.all([supabase.from('bonuses').select('*').order('sort_order').order('created_at',{ascending:false}), supabase.from('partners').select('id,name,status').order('name'), supabase.from('platform_reward_features').select('*').order('feature_key')]); if(be) throw be; if(pe) throw pe; if(fe) throw fe; setRows(b??[]); setPartners(p??[]); setFeatures(f??[]) } catch(e){toast.error(errText(e))} finally{setLoading(false)} }
  useEffect(()=>{void load()},[])
  function edit(r:any){setEditing(r.id); setForm({...r, max_claims:r.max_claims??'', starts_at:r.starts_at?.slice(0,16)??'', expires_at:r.expires_at?.slice(0,16)??'', partner_id:r.partner_id??''}); setShowForm(true)}
  function fresh(){setEditing(null);setForm(blank());setShowForm(true)}
  async function save(){try{if(!form.title.trim()) throw new Error('Title is required.'); const payload={...form, partner_id:form.partner_id||null, max_claims:form.max_claims===''?null:Number(form.max_claims), sort_order:Number(form.sort_order)||0, starts_at:form.starts_at||null, expires_at:form.expires_at||null, brand_name:form.brand_name.trim()||'Unknown Brand'}; delete payload.id; delete payload.created_at; delete payload.updated_at; const q=editing?supabase.from('bonuses').update(payload).eq('id',editing):supabase.from('bonuses').insert(payload); const {error}=await q; if(error) throw error; toast.success(editing?'Bonus updated':'Bonus created'); setShowForm(false); await load()}catch(e){toast.error(errText(e))}}
  async function remove(id:string){if(!window.confirm('Delete this bonus? This can fail when dependent grants/prizes exist.')) return; try{const {error}=await supabase.from('bonuses').delete().eq('id',id);if(error)throw error;toast.success('Bonus deleted');await load()}catch(e){toast.error(errText(e))}}
  async function setStatus(id:string,status:string){try{const {error}=await supabase.from('bonuses').update({status}).eq('id',id);if(error)throw error;toast.success(`Status set to ${status}`);await load()}catch(e){toast.error(errText(e))}}
  async function setFeatured(id:string,featured:boolean){try{const {error}=await supabase.rpc('admin_set_bonus_featured',{p_bonus_id:id,p_featured:featured});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
  async function featureToggle(key:string,enabled:boolean){try{const {error}=await supabase.rpc('set_reward_feature_enabled',{p_feature_key:key,p_enabled:enabled});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
  const stats=useMemo(()=>({active:rows.filter(r=>r.status==='active').length,featured:rows.filter(r=>r.featured).length,draft:rows.filter(r=>r.status==='draft').length}),[rows])
  return <div className="flex flex-col gap-density-lg"><PageHeader title="Bonuses" description="Partner promotions, bonus offers, access rules and reward feature switches." actions={<><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button onClick={fresh}><Plus className="h-4 w-4"/>New bonus</Button></>}/>
    <div className="grid gap-density-md md:grid-cols-3"><Metric label="Active" value={stats.active}/><Metric label="Featured" value={stats.featured}/><Metric label="Draft" value={stats.draft}/></div>
    {showForm && <Section title={editing?'Edit bonus':'Create bonus'} actions={<Button variant="ghost" size="sm" onClick={()=>setShowForm(false)}>Close</Button>}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4">
      <Field label="Partner"><select className={inputCls} value={form.partner_id} onChange={e=>setForm({...form,partner_id:e.target.value})}><option value="">No partner</option>{partners.map(p=><option key={p.id} value={p.id}>{p.name} · {p.status}</option>)}</select></Field>
      <Field label="Brand"><input className={inputCls} value={form.brand_name} onChange={e=>setForm({...form,brand_name:e.target.value})}/></Field>
      <Field label="Title"><input className={inputCls} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field>
      <Field label="Slug"><input className={inputCls} value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})}/></Field>
      <Field label="Bonus type"><select className={inputCls} value={form.bonus_type} onChange={e=>setForm({...form,bonus_type:e.target.value})}>{['deposit_bonus','free_bet','free_spin','cashback','promo_code','other'].map(v=><option key={v}>{v}</option>)}</select></Field>
      <Field label="Delivery"><select className={inputCls} value={form.delivery_type} onChange={e=>setForm({...form,delivery_type:e.target.value})}>{['code','link','code_and_link'].map(v=><option key={v}>{v}</option>)}</select></Field>
      <Field label="Access"><select className={inputCls} value={form.bonus_access_type} onChange={e=>setForm({...form,bonus_access_type:e.target.value})}>{['public','challenge','winner'].map(v=><option key={v}>{v}</option>)}</select></Field>
      <Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['draft','active','paused','expired','archived'].map(v=><option key={v}>{v}</option>)}</select></Field>
      <Field label="Promo code"><input className={inputCls} value={form.code??''} onChange={e=>setForm({...form,code:e.target.value})}/></Field>
      <Field label="Affiliate URL"><input className={inputCls} value={form.affiliate_url??''} onChange={e=>setForm({...form,affiliate_url:e.target.value})}/></Field>
      <Field label="Offer value"><input className={inputCls} value={form.offer_value??''} onChange={e=>setForm({...form,offer_value:e.target.value})}/></Field>
      <Field label="Max claims"><input className={inputCls} type="number" value={form.max_claims} onChange={e=>setForm({...form,max_claims:e.target.value})}/></Field>
      <Field label="Starts"><input className={inputCls} type="datetime-local" value={form.starts_at} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field>
      <Field label="Expires"><input className={inputCls} type="datetime-local" value={form.expires_at} onChange={e=>setForm({...form,expires_at:e.target.value})}/></Field>
      <Field label="Sort order"><input className={inputCls} type="number" value={form.sort_order} onChange={e=>setForm({...form,sort_order:e.target.value})}/></Field>
      <Field label="Brand logo URL"><input className={inputCls} value={form.brand_logo_url??''} onChange={e=>setForm({...form,brand_logo_url:e.target.value})}/></Field>
      <Field label="Image URL"><input className={inputCls} value={form.image_url??''} onChange={e=>setForm({...form,image_url:e.target.value})}/></Field>
      <Field label="Featured"><input type="checkbox" checked={!!form.featured} onChange={e=>setForm({...form,featured:e.target.checked})}/></Field>
      <div className="md:col-span-2 xl:col-span-4"><Field label="Description"><textarea className={areaCls} value={form.description??''} onChange={e=>setForm({...form,description:e.target.value})}/></Field></div>
      <div className="md:col-span-2 xl:col-span-4"><Field label="Terms"><textarea className={areaCls} value={form.terms??''} onChange={e=>setForm({...form,terms:e.target.value})}/></Field></div>
      </div><div className="mt-density-md flex justify-end"><Button onClick={()=>void save()}><Save className="h-4 w-4"/>Save</Button></div></Section>}
    <Section title="Bonus catalog"><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Offer</th><th>Type</th><th>Access</th><th>Status</th><th>Partner</th><th>Updated</th><th className="text-right">Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id} className="border-b border-border/70"><td className="py-2"><div className="font-medium">{r.title}</div><div className="text-xs text-muted-foreground">{r.brand_name}</div></td><td><StatusBadge status={r.bonus_type} dense/></td><td>{r.bonus_access_type}</td><td><StatusBadge status={r.status} dense/></td><td>{partners.find(p=>p.id===r.partner_id)?.name??'—'}</td><td>{fmt(r.updated_at)}</td><td><div className="flex justify-end gap-1"><Button variant="ghost" size="sm" onClick={()=>edit(r)}>Edit</Button><Button variant="ghost" size="sm" onClick={()=>void setFeatured(r.id,!r.featured)}>{r.featured?'Unfeature':'Feature'}</Button>{r.status==='active'?<Button variant="ghost" size="sm" onClick={()=>void setStatus(r.id,'paused')}><PowerOff className="h-3.5 w-3.5"/></Button>:<Button variant="ghost" size="sm" onClick={()=>void setStatus(r.id,'active')}><Power className="h-3.5 w-3.5"/></Button>}<Button variant="ghost" size="sm" onClick={()=>void remove(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div></td></tr>)}</tbody></table>{rows.length===0&&<div className="py-8 text-center text-sm text-muted-foreground">{loading?'Loading…':'No bonuses.'}</div>}</div></Section>
    <Section title="Reward feature switches"><div className="grid gap-2 md:grid-cols-2">{features.map(f=><div key={f.feature_key} className="flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{f.title}</div><div className="text-xs text-muted-foreground">{f.feature_key}</div></div><Button variant={f.enabled?'outline':'default'} size="sm" onClick={()=>void featureToggle(f.feature_key,!f.enabled)}>{f.enabled?'Enabled':'Disabled'}</Button></div>)}</div></Section>
  </div>
}

function Metric({label,value}:{label:string;value:React.ReactNode}){return <div className="rounded-lg border border-border bg-card p-density-lg shadow-retool-sm"><div className="text-xs uppercase tracking-wide text-muted-foreground">{label}</div><div className="mt-1 text-2xl font-semibold">{value}</div></div>}

export function GiveawaysPage(){
 const [rows,setRows]=useState<any[]>([]); const [challenges,setChallenges]=useState<any[]>([]); const [tasks,setTasks]=useState<any[]>([]); const [prizes,setPrizes]=useState<any[]>([]); const [selected,setSelected]=useState<any|null>(null); const [loading,setLoading]=useState(true)
 const [form,setForm]=useState<any>({slug:'',title:'',subtitle:'',description:'',giveaway_type:'general',status:'draft',starts_at:'',ends_at:'',featured:false,sort_order:0,image_url:'',cover_url:'',badge_text:'',prize_headline:'',participant_label:'',show_participant_count:true,show_winner_count:true,display_type:'general',challenge_id:'',metadata:'{}'})
 const [taskForm,setTaskForm]=useState<any>({task_key:'',title:'',description:'',task_type:'custom',verification_method:'manual',is_required:true,task_order:0,config:'{}',starts_at:'',ends_at:'',metadata:'{}'})
 const [prizeForm,setPrizeForm]=useState<any>({title:'',description:'',prize_type:'points',award_trigger:'winner',points_amount:'',cash_amount:'',currency:'USD',quantity:1,rank_from:'',rank_to:'',custom_data:'{}',sort_order:0,metadata:'{}'})
 async function load(){setLoading(true);try{const [{data:g,error:ge},{data:c,error:ce}]=await Promise.all([supabase.from('giveaways').select('*').order('sort_order').order('created_at',{ascending:false}),supabase.from('challenges').select('*').order('created_at',{ascending:false})]);if(ge)throw ge;if(ce)throw ce;setRows(g??[]);setChallenges(c??[]);if(selected){const [t,p]=await Promise.all([supabase.from('challenge_tasks').select('*').eq('challenge_id',selected.challenge_id).order('task_order'),supabase.from('challenge_prizes').select('*').eq('challenge_id',selected.challenge_id).order('sort_order')]);setTasks(t.data??[]);setPrizes(p.data??[])}}catch(e){toast.error(errText(e))}finally{setLoading(false)}} useEffect(()=>{void load()},[])
 function pick(r:any){setSelected(r);setForm({...r,starts_at:r.starts_at?.slice(0,16)??'',ends_at:r.ends_at?.slice(0,16)??'',metadata:JSON.stringify(r.metadata??{},null,2)})}
 async function save(){try{parseJson(form.metadata);const payload={...form,challenge_id:form.challenge_id,sort_order:Number(form.sort_order)||0,starts_at:form.starts_at||null,ends_at:form.ends_at||null,metadata:parseJson(form.metadata)};delete payload.id;delete payload.created_at;delete payload.updated_at;const {data,error}=await supabase.from('giveaways').insert(payload).select().single();if(error)throw error;toast.success('Giveaway created');setSelected(data);await load()}catch(e){toast.error(errText(e))}}
 async function update(){try{const payload={...form,sort_order:Number(form.sort_order)||0,starts_at:form.starts_at||null,ends_at:form.ends_at||null,metadata:parseJson(form.metadata)};delete payload.id;delete payload.created_at;delete payload.updated_at;const {error}=await supabase.from('giveaways').update(payload).eq('id',selected.id);if(error)throw error;toast.success('Giveaway updated');await load();setSelected({...selected,...payload})}catch(e){toast.error(errText(e))}}
 async function addTask(){try{const {error}=await supabase.from('challenge_tasks').insert({...taskForm,challenge_id:selected.challenge_id,task_order:Number(taskForm.task_order)||0,config:parseJson(taskForm.config),metadata:parseJson(taskForm.metadata),starts_at:taskForm.starts_at||null,ends_at:taskForm.ends_at||null});if(error)throw error;toast.success('Task added');setTaskForm({...taskForm,task_key:'',title:'',description:''});await load()}catch(e){toast.error(errText(e))}}
 async function addPrize(){try{const payload={...prizeForm,challenge_id:selected.challenge_id,points_amount:prizeForm.points_amount===''?null:Number(prizeForm.points_amount),cash_amount:prizeForm.cash_amount===''?null:Number(prizeForm.cash_amount),rank_from:prizeForm.rank_from===''?null:Number(prizeForm.rank_from),rank_to:prizeForm.rank_to===''?null:Number(prizeForm.rank_to),quantity:Number(prizeForm.quantity)||1,sort_order:Number(prizeForm.sort_order)||0,custom_data:parseJson(prizeForm.custom_data),metadata:parseJson(prizeForm.metadata)};const {error}=await supabase.from('challenge_prizes').insert(payload);if(error)throw error;toast.success('Prize added');await load()}catch(e){toast.error(errText(e))}}
 async function del(table:string,id:string){if(!window.confirm('Delete this item?'))return;try{const {error}=await supabase.from(table).delete().eq('id',id);if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Giveaways" description="Giveaway presentation layer with linked challenge tasks and prizes." actions={<Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button>}/><Section title="Giveaways"><div className="grid gap-2">{rows.map(r=><button key={r.id} onClick={()=>pick(r)} className={`rounded-md border p-3 text-left hover:bg-muted/40 ${selected?.id===r.id?'border-foreground':'border-border'}`}><div className="flex items-center justify-between gap-3"><div><div className="font-medium">{r.title}</div><div className="text-xs text-muted-foreground">/{r.slug} · {r.display_type}</div></div><StatusBadge status={r.status} dense/></div></button>)}{rows.length===0&&<div className="py-8 text-center text-sm text-muted-foreground">{loading?'Loading…':'No giveaways.'}</div>}</div></Section>
 {selected&&<Section title={`Manage: ${selected.title}`}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Title"><input className={inputCls} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><Field label="Slug"><input className={inputCls} value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})}/></Field><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['draft','active','paused','ended','cancelled'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Display type"><select className={inputCls} value={form.display_type} onChange={e=>setForm({...form,display_type:e.target.value})}>{['general','social','telegram','prediction','random_draw','mixed','tournament','pickrush','prize_pool','special','custom'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Giveaway type"><select className={inputCls} value={form.giveaway_type} onChange={e=>setForm({...form,giveaway_type:e.target.value})}>{['general','social','telegram','prediction','random_draw','mixed','tournament','special'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Challenge"><select className={inputCls} value={form.challenge_id} onChange={e=>setForm({...form,challenge_id:e.target.value})}>{challenges.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></Field><Field label="Starts"><input className={inputCls} type="datetime-local" value={form.starts_at} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field><Field label="Ends"><input className={inputCls} type="datetime-local" value={form.ends_at} onChange={e=>setForm({...form,ends_at:e.target.value})}/></Field><Field label="Featured"><input type="checkbox" checked={!!form.featured} onChange={e=>setForm({...form,featured:e.target.checked})}/></Field><Field label="Sort order"><input className={inputCls} type="number" value={form.sort_order} onChange={e=>setForm({...form,sort_order:e.target.value})}/></Field><Field label="Image URL"><input className={inputCls} value={form.image_url??''} onChange={e=>setForm({...form,image_url:e.target.value})}/></Field><Field label="Cover URL"><input className={inputCls} value={form.cover_url??''} onChange={e=>setForm({...form,cover_url:e.target.value})}/></Field><Field label="Badge text"><input className={inputCls} value={form.badge_text??''} onChange={e=>setForm({...form,badge_text:e.target.value})}/></Field><Field label="Prize headline"><input className={inputCls} value={form.prize_headline??''} onChange={e=>setForm({...form,prize_headline:e.target.value})}/></Field><div className="md:col-span-2 xl:col-span-4"><Field label="Description"><textarea className={areaCls} value={form.description??''} onChange={e=>setForm({...form,description:e.target.value})}/></Field></div><div className="md:col-span-2 xl:col-span-4"><Field label="Metadata JSON"><JsonField value={form.metadata} onChange={v=>setForm({...form,metadata:v})}/></Field></div></div><div className="mt-density-md flex gap-2 justify-end"><Button variant="outline" onClick={()=>setForm({...selected,starts_at:selected.starts_at?.slice(0,16)??'',ends_at:selected.ends_at?.slice(0,16)??'',metadata:JSON.stringify(selected.metadata??{},null,2)})}>Reset</Button><Button onClick={()=>void update()}><Save className="h-4 w-4"/>Update giveaway</Button></div>
 <div className="mt-density-xl grid gap-density-lg xl:grid-cols-2"><div><div className="mb-2 font-semibold">Tasks</div><div className="space-y-2">{tasks.map(t=><div key={t.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div><div className="font-medium">{t.title}</div><div className="text-xs text-muted-foreground">{t.task_type} · {t.verification_method}</div></div><Button variant="ghost" size="sm" onClick={()=>void del('challenge_tasks',t.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div></div>)}<div className="rounded-md border border-dashed border-border p-3"><div className="grid gap-2 md:grid-cols-2"><input className={inputCls} placeholder="Task key" value={taskForm.task_key} onChange={e=>setTaskForm({...taskForm,task_key:e.target.value})}/><input className={inputCls} placeholder="Title" value={taskForm.title} onChange={e=>setTaskForm({...taskForm,title:e.target.value})}/><select className={inputCls} value={taskForm.task_type} onChange={e=>setTaskForm({...taskForm,task_type:e.target.value})}>{['social_follow','social_comment','telegram_join','prediction','custom','manual'].map(v=><option key={v}>{v}</option>)}</select><select className={inputCls} value={taskForm.verification_method} onChange={e=>setTaskForm({...taskForm,verification_method:e.target.value})}>{['automatic','manual','external','result_based'].map(v=><option key={v}>{v}</option>)}</select></div><div className="mt-2"><textarea className={areaCls} placeholder="Task description" value={taskForm.description} onChange={e=>setTaskForm({...taskForm,description:e.target.value})}/></div><Button className="mt-2" size="sm" onClick={()=>void addTask()}><Plus className="h-3.5 w-3.5"/>Add task</Button></div></div></div>
 <div><div className="mb-2 font-semibold">Prizes</div><div className="space-y-2">{prizes.map(p=><div key={p.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div><div className="font-medium">{p.title}</div><div className="text-xs text-muted-foreground">{p.prize_type} · {p.award_trigger}</div></div><Button variant="ghost" size="sm" onClick={()=>void del('challenge_prizes',p.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div></div>)}<div className="rounded-md border border-dashed border-border p-3"><div className="grid gap-2 md:grid-cols-2"><input className={inputCls} placeholder="Prize title" value={prizeForm.title} onChange={e=>setPrizeForm({...prizeForm,title:e.target.value})}/><select className={inputCls} value={prizeForm.prize_type} onChange={e=>setPrizeForm({...prizeForm,prize_type:e.target.value})}>{['points','cash','bonus','custom'].map(v=><option key={v}>{v}</option>)}</select><select className={inputCls} value={prizeForm.award_trigger} onChange={e=>setPrizeForm({...prizeForm,award_trigger:e.target.value})}>{['completion','winner'].map(v=><option key={v}>{v}</option>)}</select><input className={inputCls} placeholder="Points" type="number" value={prizeForm.points_amount} onChange={e=>setPrizeForm({...prizeForm,points_amount:e.target.value})}/><input className={inputCls} placeholder="Cash" type="number" value={prizeForm.cash_amount} onChange={e=>setPrizeForm({...prizeForm,cash_amount:e.target.value})}/><input className={inputCls} placeholder="Currency" value={prizeForm.currency} onChange={e=>setPrizeForm({...prizeForm,currency:e.target.value})}/><input className={inputCls} placeholder="Rank from" type="number" value={prizeForm.rank_from} onChange={e=>setPrizeForm({...prizeForm,rank_from:e.target.value})}/><input className={inputCls} placeholder="Rank to" type="number" value={prizeForm.rank_to} onChange={e=>setPrizeForm({...prizeForm,rank_to:e.target.value})}/></div><Button className="mt-2" size="sm" onClick={()=>void addPrize()}><Plus className="h-3.5 w-3.5"/>Add prize</Button></div></div></div></div></Section>}
 </div>
}

export function PickRushPage(){
 const [rows,setRows]=useState<any[]>([]); const [selected,setSelected]=useState<any|null>(null); const [participants,setParticipants]=useState<any[]>([]); const [form,setForm]=useState<any>({status:'draft'}); const [loading,setLoading]=useState(true)
 async function load(){setLoading(true);try{const {data,error}=await supabase.from('pickrush_contests').select('*, partners(name)').order('starts_at',{ascending:false});if(error)throw error;setRows(data??[]);if(selected){const {data:p,error:pe}=await supabase.rpc('get_pickrush_participants',{p_contest_id:selected.id});if(pe)throw pe;setParticipants(Array.isArray(p)?p:[]);const c=data?.find((x:any)=>x.id===selected.id);if(c){setSelected(c);setForm(c)}}}catch(e){toast.error(errText(e))}finally{setLoading(false)}} useEffect(()=>{void load()},[])
 function pick(r:any){setSelected(r);setForm(r)}
 async function update(){try{const payload={status:form.status,starts_at:form.starts_at,ends_at:form.ends_at,participant_limit:form.participant_limit?Number(form.participant_limit):null,close_rule:form.close_rule,platform_partner_id:form.platform_partner_id||null,platform_url:form.platform_url||null,required_matches:Number(form.required_matches),min_total_odds:Number(form.min_total_odds),max_total_odds:form.max_total_odds===''?null:Number(form.max_total_odds),virtual_stake:Number(form.virtual_stake),max_entries_per_user:Number(form.max_entries_per_user),campaign_percent:Number(form.campaign_percent),metadata:typeof form.metadata==='string'?parseJson(form.metadata):form.metadata??{}};const {error}=await supabase.from('pickrush_contests').update(payload).eq('id',selected.id);if(error)throw error;toast.success('Pick Rush updated');await load()}catch(e){toast.error(errText(e))}}
 async function action(fn:string){try{const {data,error}=await supabase.rpc(fn,{p_contest_id:selected.id});if(error)throw error;toast.success(`${fn.replaceAll('_',' ')}`);await load();return data}catch(e){toast.error(errText(e))}}
 async function create(){try{const {data,error}=await supabase.rpc('create_pickrush_contest',{p_title:'New Pick Rush',p_slug:`pickrush-${Date.now()}`,p_description:'',p_starts_at:new Date().toISOString(),p_ends_at:new Date(Date.now()+86400000).toISOString(),p_participant_limit:null,p_close_rule:'time_only',p_platform_partner_id:null,p_platform_url:null,p_required_matches:3,p_min_total_odds:1,p_max_total_odds:null,p_virtual_stake:100,p_image_url:null,p_metadata:{}});if(error)throw error;toast.success('Pick Rush created');await load();if(data){const id=(data as any).id??data;const r=rows.find(x=>x.id===id);if(r)pick(r)}}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Pick Rush" description="Contest lifecycle, constraints, partner routing, submissions and operational actions." actions={<><Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button onClick={()=>void create()}><Plus className="h-4 w-4"/>Create contest</Button></>}/><Section title="Contests"><div className="grid gap-2">{rows.map(r=><button key={r.id} onClick={()=>pick(r)} className={`rounded-md border p-3 text-left ${selected?.id===r.id?'border-foreground':'border-border'}`}><div className="flex items-center justify-between"><div><div className="font-medium">{r.status}</div><div className="text-xs text-muted-foreground">{fmt(r.starts_at)} → {fmt(r.ends_at)}</div></div><StatusBadge status={r.status} dense/></div></button>)}</div>{rows.length===0&&<div className="py-8 text-center text-sm text-muted-foreground">{loading?'Loading…':'No contests.'}</div>}</Section>{selected&&<Section title="Contest controls"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['draft','scheduled','open','full','closed','awaiting_results','settling','completed','cancelled'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Starts"><input className={inputCls} type="datetime-local" value={form.starts_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field><Field label="Ends"><input className={inputCls} type="datetime-local" value={form.ends_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,ends_at:e.target.value})}/></Field><Field label="Participant limit"><input className={inputCls} type="number" value={form.participant_limit??''} onChange={e=>setForm({...form,participant_limit:e.target.value})}/></Field><Field label="Close rule"><select className={inputCls} value={form.close_rule} onChange={e=>setForm({...form,close_rule:e.target.value})}>{['time_only','participant_limit_only','time_or_limit','time_and_limit','manual'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Required matches"><input className={inputCls} type="number" value={form.required_matches} onChange={e=>setForm({...form,required_matches:e.target.value})}/></Field><Field label="Min total odds"><input className={inputCls} type="number" step="0.01" value={form.min_total_odds} onChange={e=>setForm({...form,min_total_odds:e.target.value})}/></Field><Field label="Max total odds"><input className={inputCls} type="number" step="0.01" value={form.max_total_odds??''} onChange={e=>setForm({...form,max_total_odds:e.target.value})}/></Field><Field label="Virtual stake"><input className={inputCls} type="number" value={form.virtual_stake} onChange={e=>setForm({...form,virtual_stake:e.target.value})}/></Field><Field label="Max entries/user"><input className={inputCls} type="number" value={form.max_entries_per_user} onChange={e=>setForm({...form,max_entries_per_user:e.target.value})}/></Field><Field label="Campaign %"><input className={inputCls} type="number" value={form.campaign_percent} onChange={e=>setForm({...form,campaign_percent:e.target.value})}/></Field><Field label="Platform URL"><input className={inputCls} value={form.platform_url??''} onChange={e=>setForm({...form,platform_url:e.target.value})}/></Field></div><div className="mt-density-md flex flex-wrap justify-between gap-2"><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>void action('open_pickrush')}><Play className="h-4 w-4"/>Open</Button><Button variant="outline" onClick={()=>void action('lock_pickrush_contest')}><LockKeyhole className="h-4 w-4"/>Lock</Button><Button variant="outline" onClick={()=>void action('close_pickrush')}><PowerOff className="h-4 w-4"/>Close</Button><Button variant="outline" onClick={()=>void action('finalize_pickrush_contest')}><Trophy className="h-4 w-4"/>Finalize</Button><Button variant="outline" onClick={()=>void action('refresh_pickrush_contest_state')}><RotateCcw className="h-4 w-4"/>Refresh state</Button></div><Button onClick={()=>void update()}><Save className="h-4 w-4"/>Save</Button></div><div className="mt-density-lg"><div className="mb-2 font-semibold">Participants</div><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">User</th><th>Status</th><th>Code</th><th>Score</th><th>Rank</th></tr></thead><tbody>{participants.map((p:any,i:number)=><tr key={p.id??i} className="border-b border-border/70"><td className="py-2">{p.username??p.full_name??p.user_id}</td><td>{p.status}</td><td>{p.registration_code??'—'}</td><td>{p.score??0}</td><td>{p.rank??'—'}</td></tr>)}</tbody></table></div></div></Section>}</div>
}

export function PrizePoolPage(){
 const [rows,setRows]=useState<any[]>([]); const [selected,setSelected]=useState<any|null>(null); const [tiers,setTiers]=useState<any[]>([]); const [rules,setRules]=useState<any[]>([]); const [awards,setAwards]=useState<any[]>([]); const [form,setForm]=useState<any>({}); const [tier,setTier]=useState<any>({rank_from:1,rank_to:1,reward_amount:1,currency:'TND',title:'',description:'',sort_order:0}); const [rule,setRule]=useState<any>({rule_key:'',rule_type:'account_age',operator:'gte',value:'{}',is_required:true,enabled:true,sort_order:0,title:'',description:'',metadata:'{}'})
 async function load(){try{const {data,error}=await supabase.from('prize_pool_campaigns').select('*').order('starts_at',{ascending:false});if(error)throw error;setRows(data??[]);if(selected){const c=data?.find((x:any)=>x.id===selected.id);if(c){setSelected(c);setForm({...c,metadata:JSON.stringify(c.metadata??{},null,2),eligibility_rules:JSON.stringify(c.eligibility_rules??{},null,2)});const [t,r,a]=await Promise.all([supabase.from('prize_pool_reward_tiers').select('*').eq('campaign_id',c.id).order('sort_order'),supabase.from('prize_pool_eligibility_rules').select('*').eq('campaign_id',c.id).order('sort_order'),supabase.rpc('admin_get_prize_pool_awards',{p_campaign_id:c.id})]);setTiers(t.data??[]);setRules(r.data??[]);setAwards(Array.isArray(a.data)?a.data:[])}}}catch(e){toast.error(errText(e))}}
 useEffect(()=>{void load()},[])
 async function create(){try{const {error}=await supabase.rpc('create_prize_pool_campaign',{p_slug:`prize-pool-${Date.now()}`,p_title:'New Prize Pool',p_description:'',p_starts_at:new Date().toISOString(),p_ends_at:new Date(Date.now()+86400000*7).toISOString(),p_process_at:new Date(Date.now()+86400000*7+3600000).toISOString(),p_pool_amount:100,p_currency:'USD',p_rewarded_positions:10,p_leaderboard_metric:'current_balance'});if(error)throw error;toast.success('Prize pool created');await load()}catch(e){toast.error(errText(e))}}
 function pick(r:any){setSelected(r);setForm({...r,metadata:JSON.stringify(r.metadata??{},null,2),eligibility_rules:JSON.stringify(r.eligibility_rules??{},null,2)})}
 async function update(){try{const payload={...form,pool_amount:Number(form.pool_amount),rewarded_positions:Number(form.rewarded_positions),max_entries_per_user:Number(form.max_entries_per_user),min_account_age_days:form.min_account_age_days===''||form.min_account_age_days==null?null:Number(form.min_account_age_days),eligibility_rules:parseJson(form.eligibility_rules),metadata:parseJson(form.metadata)};delete payload.id;delete payload.created_at;delete payload.updated_at;const {error}=await supabase.from('prize_pool_campaigns').update(payload).eq('id',selected.id);if(error)throw error;toast.success('Prize pool updated');await load()}catch(e){toast.error(errText(e))}}
 async function addTier(){try{const {error}=await supabase.from('prize_pool_reward_tiers').insert({...tier,campaign_id:selected.id,rank_from:Number(tier.rank_from),rank_to:Number(tier.rank_to),reward_amount:Number(tier.reward_amount),sort_order:Number(tier.sort_order)||0});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function addRule(){try{const {error}=await supabase.from('prize_pool_eligibility_rules').insert({...rule,campaign_id:selected.id,value:parseJson(rule.value),sort_order:Number(rule.sort_order)||0,metadata:parseJson(rule.metadata)});if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 async function action(fn:string){try{const {data,error}=await supabase.rpc(fn,{p_campaign_id:selected.id});if(error)throw error;toast.success(`${fn.replaceAll('_',' ')}`);await load();console.debug(data)}catch(e){toast.error(errText(e))}}
 async function del(table:string,id:string){if(!window.confirm('Delete this item?'))return;try{const {error}=await supabase.from(table).delete().eq('id',id);if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Prize Pool" description="Prize pool campaigns, reward tiers, eligibility rules, processing state and awards." actions={<><Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button onClick={()=>void create()}><Plus className="h-4 w-4"/>Create pool</Button></>}/><Section title="Campaigns"><div className="grid gap-2">{rows.map(r=><button key={r.id} onClick={()=>pick(r)} className={`rounded-md border p-3 text-left ${selected?.id===r.id?'border-foreground':'border-border'}`}><div className="flex items-center justify-between"><div><div className="font-medium">{r.title}</div><div className="text-xs text-muted-foreground">{r.slug} · {r.pool_amount} {r.currency}</div></div><StatusBadge status={r.status} dense/></div></button>)}</div></Section>{selected&&<Section title={`Manage: ${selected.title}`}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['draft','scheduled','open','closed','processing','processed','cancelled'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Starts"><input className={inputCls} type="datetime-local" value={form.starts_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,starts_at:e.target.value})}/></Field><Field label="Ends"><input className={inputCls} type="datetime-local" value={form.ends_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,ends_at:e.target.value})}/></Field><Field label="Process at"><input className={inputCls} type="datetime-local" value={form.process_at?.slice?.(0,16)??''} onChange={e=>setForm({...form,process_at:e.target.value})}/></Field><Field label="Pool amount"><input className={inputCls} type="number" value={form.pool_amount} onChange={e=>setForm({...form,pool_amount:e.target.value})}/></Field><Field label="Currency"><input className={inputCls} value={form.currency} onChange={e=>setForm({...form,currency:e.target.value})}/></Field><Field label="Rewarded positions"><input className={inputCls} type="number" value={form.rewarded_positions} onChange={e=>setForm({...form,rewarded_positions:e.target.value})}/></Field><Field label="Leaderboard metric"><select className={inputCls} value={form.leaderboard_metric} onChange={e=>setForm({...form,leaderboard_metric:e.target.value})}>{['current_balance','lifetime_earned'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Distribution"><select className={inputCls} value={form.distribution_method} onChange={e=>setForm({...form,distribution_method:e.target.value})}>{['equal','tiered'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Eligibility mode"><select className={inputCls} value={form.eligibility_mode} onChange={e=>setForm({...form,eligibility_mode:e.target.value})}>{['open','account_age','joined_only'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Max entries/user"><input className={inputCls} type="number" value={form.max_entries_per_user} onChange={e=>setForm({...form,max_entries_per_user:e.target.value})}/></Field><Field label="Min account age days"><input className={inputCls} type="number" value={form.min_account_age_days??''} onChange={e=>setForm({...form,min_account_age_days:e.target.value})}/></Field></div><div className="mt-density-md flex flex-wrap justify-between gap-2"><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>void action('refresh_prize_pool_statuses')}><RotateCcw className="h-4 w-4"/>Refresh statuses</Button><Button variant="outline" onClick={()=>void action('process_prize_pool')}><Play className="h-4 w-4"/>Process</Button></div><Button onClick={()=>void update()}><Save className="h-4 w-4"/>Save</Button></div><div className="mt-density-xl grid gap-density-lg xl:grid-cols-3"><div><div className="mb-2 font-semibold">Reward tiers</div>{tiers.map(t=><div key={t.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div>#{t.rank_from}-{t.rank_to} · {t.reward_amount} {t.currency}</div><Button variant="ghost" size="sm" onClick={()=>void del('prize_pool_reward_tiers',t.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>)}<div className="rounded-md border border-dashed border-border p-3 grid gap-2"><input className={inputCls} placeholder="Rank from" type="number" value={tier.rank_from} onChange={e=>setTier({...tier,rank_from:e.target.value})}/><input className={inputCls} placeholder="Rank to" type="number" value={tier.rank_to} onChange={e=>setTier({...tier,rank_to:e.target.value})}/><input className={inputCls} placeholder="Reward amount" type="number" value={tier.reward_amount} onChange={e=>setTier({...tier,reward_amount:e.target.value})}/><input className={inputCls} placeholder="Currency" value={tier.currency} onChange={e=>setTier({...tier,currency:e.target.value})}/><Button size="sm" onClick={()=>void addTier()}><Plus className="h-3.5 w-3.5"/>Add tier</Button></div></div><div><div className="mb-2 font-semibold">Eligibility rules</div>{rules.map(r=><div key={r.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{r.title||r.rule_key}</div><div className="text-xs text-muted-foreground">{r.rule_type} {r.operator}</div></div><Button variant="ghost" size="sm" onClick={()=>void del('prize_pool_eligibility_rules',r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>)}<div className="rounded-md border border-dashed border-border p-3 grid gap-2"><input className={inputCls} placeholder="Rule key" value={rule.rule_key} onChange={e=>setRule({...rule,rule_key:e.target.value})}/><select className={inputCls} value={rule.rule_type} onChange={e=>setRule({...rule,rule_type:e.target.value})}>{['account_age','country','min_points','max_points','lifetime_points','profile_completion','account_status','excluded_role','required_role','signup_before','signup_after','minimum_activity','custom'].map(v=><option key={v}>{v}</option>)}</select><select className={inputCls} value={rule.operator} onChange={e=>setRule({...rule,operator:e.target.value})}>{['eq','neq','gt','gte','lt','lte','in','not_in'].map(v=><option key={v}>{v}</option>)}</select><JsonField value={rule.value} onChange={v=>setRule({...rule,value:v})}/><Button size="sm" onClick={()=>void addRule()}><Plus className="h-3.5 w-3.5"/>Add rule</Button></div></div><div><div className="mb-2 font-semibold">Awards</div><div className="space-y-2">{awards.map((a:any,i:number)=><div key={a.id??i} className="rounded-md border border-border p-3 text-sm"><div className="font-medium">Rank {a.rank} · {a.amount} {a.currency}</div><div className="text-xs text-muted-foreground">{a.status} · user {a.user_id}</div></div>)}{awards.length===0&&<div className="text-sm text-muted-foreground">No awards yet.</div>}</div></div></div></Section>}</div>
}

export function BookmakersRadarPage(){
 const [rows,setRows]=useState<any[]>([]); const [reports,setReports]=useState<any[]>([]); const [incidents,setIncidents]=useState<any[]>([]); const [selected,setSelected]=useState<any|null>(null); const [form,setForm]=useState<any>({})
 async function load(){try{const [{data:b,error:be},{data:r,error:re},{data:i,error:ie}]=await Promise.all([supabase.from('bookmakers_radar').select('*').order('priority').order('name'),supabase.from('bookmaker_reports').select('*').order('submitted_at',{ascending:false}),supabase.from('bookmaker_incidents').select('*').order('published_at',{ascending:false})]);if(be)throw be;if(re)throw re;if(ie)throw ie;setRows(b??[]);setReports(r??[]);setIncidents(i??[])}catch(e){toast.error(errText(e))}}
 useEffect(()=>{void load()},[])
 function pick(r:any){setSelected(r);setForm({...r,metadata:JSON.stringify(r.metadata??{},null,2)})}
 async function save(){try{const payload={...form,radar_score:form.radar_score===''?null:Number(form.radar_score),verified_reports:Number(form.verified_reports)||0,unresolved_reports:Number(form.unresolved_reports)||0,resolved_reports:Number(form.resolved_reports)||0,repeated_patterns:Number(form.repeated_patterns)||0,priority:Number(form.priority)||100,metadata:parseJson(form.metadata)};delete payload.id;delete payload.created_at;delete payload.updated_at;const {error}=await supabase.from('bookmakers_radar').update(payload).eq('id',selected.id);if(error)throw error;toast.success('Bookmaker updated');await load()}catch(e){toast.error(errText(e))}}
 async function newBookmaker(){try{const {data,error}=await supabase.from('bookmakers_radar').insert({name:'New Bookmaker',slug:`bookmaker-${Date.now()}`}).select().single();if(error)throw error;pick(data);await load()}catch(e){toast.error(errText(e))}}
 async function recompute(id?:string){try{const {error}=id?await supabase.rpc('recompute_bookmaker_radar',{p_bookmaker_id:id}):await supabase.rpc('recompute_all_bookmakers_radar');if(error)throw error;toast.success('Radar recomputed');await load()}catch(e){toast.error(errText(e))}}
 async function publish(report:any){try{const {error}=await supabase.rpc('admin_publish_bookmaker_report',{p_report_id:report.id,p_title:report.custom_brand_name??report.reference_code,p_summary:report.description,p_severity:'moderate',p_evidence_strength:'moderate',p_resolution_status:'unresolved',p_amount:report.amount??null,p_currency:report.currency??null});if(error)throw error;toast.success('Report published');await load()}catch(e){toast.error(errText(e))}}
 async function resolve(i:any){try{const {error}=await supabase.rpc('admin_resolve_bookmaker_incident',{p_incident_id:i.id,p_resolution_note:'Resolved from Admin Radar.'});if(error)throw error;toast.success('Incident resolved');await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Bookmakers Radar" description="Bookmaker metadata, safety signals, verification, reports and incident workflow." actions={<><Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button variant="outline" onClick={()=>void recompute()}><RotateCcw className="h-4 w-4"/>Recompute all</Button><Button onClick={()=>void newBookmaker()}><Plus className="h-4 w-4"/>New bookmaker</Button></>}/><Section title="Bookmakers"><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{rows.map(r=><button key={r.id} onClick={()=>pick(r)} className={`rounded-md border p-3 text-left ${selected?.id===r.id?'border-foreground':'border-border'}`}><div className="flex items-center justify-between"><div><div className="font-medium">{r.name}</div><div className="text-xs text-muted-foreground">{r.slug} · priority {r.priority}</div></div><StatusBadge status={r.status} dense/></div><div className="mt-2 text-xs text-muted-foreground">Radar {r.radar_score??'—'} · Risk {r.risk_level} · {r.current_signal}</div></button>)}</div></Section>{selected&&<Section title={`Edit: ${selected.name}`}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Name"><input className={inputCls} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Slug"><input className={inputCls} value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})}/></Field><Field label="Short name"><input className={inputCls} value={form.short_name??''} onChange={e=>setForm({...form,short_name:e.target.value})}/></Field><Field label="Website"><input className={inputCls} value={form.website??''} onChange={e=>setForm({...form,website:e.target.value})}/></Field><Field label="Country"><input className={inputCls} value={form.country??''} onChange={e=>setForm({...form,country:e.target.value})}/></Field><Field label="Status"><select className={inputCls} value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['active','inactive','archived'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Risk"><select className={inputCls} value={form.risk_level} onChange={e=>setForm({...form,risk_level:e.target.value})}>{['low','medium','high','critical','insufficient_data'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Signal"><select className={inputCls} value={form.current_signal} onChange={e=>setForm({...form,current_signal:e.target.value})}>{['strong_safety_signals','generally_stable','mixed_safety_signals','elevated_concern','critical_concern','insufficient_data'].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Radar score"><input className={inputCls} type="number" min="0" max="100" value={form.radar_score??''} onChange={e=>setForm({...form,radar_score:e.target.value})}/></Field><Field label="Verified"><input type="checkbox" checked={!!form.verified} onChange={e=>setForm({...form,verified:e.target.checked})}/></Field><Field label="Sharp"><input type="checkbox" checked={!!form.is_sharp} onChange={e=>setForm({...form,is_sharp:e.target.checked})}/></Field><Field label="Provider enabled"><input type="checkbox" checked={!!form.data_provider_enabled} onChange={e=>setForm({...form,data_provider_enabled:e.target.checked})}/></Field><Field label="Priority"><input className={inputCls} type="number" value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}/></Field><Field label="Discovery source"><select className={inputCls} value={form.discovery_source??'admin'} onChange={e=>setForm({...form,discovery_source:e.target.value})}>{['admin','system','user_report','import'].map(v=><option key={v}>{v}</option>)}</select></Field><div className="md:col-span-2 xl:col-span-4"><Field label="Description"><textarea className={areaCls} value={form.description??''} onChange={e=>setForm({...form,description:e.target.value})}/></Field></div></div><div className="mt-density-md flex gap-2 justify-end"><Button variant="outline" onClick={()=>void recompute(selected.id)}><RotateCcw className="h-4 w-4"/>Recompute</Button><Button onClick={()=>void save()}><Save className="h-4 w-4"/>Save</Button></div></Section>}
 <div className="grid gap-density-lg xl:grid-cols-2"><Section title="Reports"><div className="space-y-2">{reports.map(r=><div key={r.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div><div className="font-medium">{r.reference_code}</div><div className="text-xs text-muted-foreground">{r.category} · {fmt(r.submitted_at)}</div></div><StatusBadge status={r.status} dense/></div><div className="mt-2 flex justify-end">{['submitted','under_review'].includes(r.status)&&<Button size="sm" variant="outline" onClick={()=>void publish(r)}>Publish / verify</Button>}</div></div>)}</div></Section><Section title="Incidents"><div className="space-y-2">{incidents.map(i=><div key={i.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div className="font-medium">{i.title}</div><StatusBadge status={i.resolution_status} dense/></div><div className="mt-1 text-xs text-muted-foreground">{i.severity} · {i.evidence_strength}</div>{i.resolution_status==='unresolved'&&<div className="mt-2 flex justify-end"><Button size="sm" variant="outline" onClick={()=>void resolve(i)}>Resolve</Button></div>}</div>)}</div></Section></div></div>
}

export function LeaderboardsPage(){
 const [board,setBoard]=useState<any[]>([]); const [bots,setBots]=useState<any[]>([]); const [bot,setBot]=useState<any>({username:'',full_name:'',avatar_id:'',points:0,is_active:true,date_of_birth:'',country:'',city:'',address:'',facebook:'',telegram:'',whatsapp:'',bio:'',phone:'',status:'active'}); const [editing,setEditing]=useState<string|null>(null)
 async function load(){try{const [{data:b,error:be},{data:bo,error:boe}]=await Promise.all([supabase.rpc('get_leaderboard',{p_limit:100,p_offset:0}),supabase.from('leaderboard_bots').select('*').order('points',{ascending:false})]);if(be)throw be;if(boe)throw boe;setBoard(Array.isArray(b)?b:[]);setBots(bo??[])}catch(e){toast.error(errText(e))}}
 useEffect(()=>{void load()},[])
 function edit(r:any){setEditing(r.id);setBot({...r})}
 function fresh(){setEditing(null);setBot({username:'',full_name:'',avatar_id:'',points:0,is_active:true,date_of_birth:'',country:'',city:'',address:'',facebook:'',telegram:'',whatsapp:'',bio:'',phone:'',status:'active'})}
 async function saveBot(){try{const payload={...bot,points:Number(bot.points)||0};if(editing){delete payload.id;delete payload.created_at;const {error}=await supabase.from('leaderboard_bots').update(payload).eq('id',editing);if(error)throw error}else{delete payload.id;const {error}=await supabase.from('leaderboard_bots').insert(payload);if(error)throw error}toast.success(editing?'Bot updated':'Bot created');fresh();await load()}catch(e){toast.error(errText(e))}}
 async function del(id:string){if(!window.confirm('Delete this leaderboard bot?'))return;try{const {error}=await supabase.from('leaderboard_bots').delete().eq('id',id);if(error)throw error;await load()}catch(e){toast.error(errText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Leaderboards" description="Live leaderboard visibility plus synthetic leaderboard bot administration." actions={<><Button variant="outline" onClick={()=>void load()}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button onClick={fresh}><Plus className="h-4 w-4"/>New bot</Button></>}/><Section title="Live leaderboard"><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Rank</th><th>User</th><th>Points</th><th>Current user</th></tr></thead><tbody>{board.map((r:any,i:number)=><tr key={r.user_id??i} className="border-b border-border/70"><td className="py-2">{r.rank}</td><td>{r.username??r.full_name??r.user_id}</td><td>{Number(r.points??0).toLocaleString()}</td><td>{r.is_current_user?'Yes':''}</td></tr>)}</tbody></table></div></Section><Section title={editing?'Edit leaderboard bot':'Create leaderboard bot'}><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-4"><Field label="Username"><input className={inputCls} value={bot.username} onChange={e=>setBot({...bot,username:e.target.value})}/></Field><Field label="Full name"><input className={inputCls} value={bot.full_name??''} onChange={e=>setBot({...bot,full_name:e.target.value})}/></Field><Field label="Points"><input className={inputCls} type="number" value={bot.points} onChange={e=>setBot({...bot,points:e.target.value})}/></Field><Field label="Status"><input className={inputCls} value={bot.status??''} onChange={e=>setBot({...bot,status:e.target.value})}/></Field><Field label="Country"><input className={inputCls} value={bot.country??''} onChange={e=>setBot({...bot,country:e.target.value})}/></Field><Field label="City"><input className={inputCls} value={bot.city??''} onChange={e=>setBot({...bot,city:e.target.value})}/></Field><Field label="Avatar ID"><input className={inputCls} value={bot.avatar_id??''} onChange={e=>setBot({...bot,avatar_id:e.target.value})}/></Field><Field label="Active"><input type="checkbox" checked={!!bot.is_active} onChange={e=>setBot({...bot,is_active:e.target.checked})}/></Field></div><div className="mt-density-md flex justify-end gap-2"><Button variant="outline" onClick={fresh}>Clear</Button><Button onClick={()=>void saveBot()}><Save className="h-4 w-4"/>Save bot</Button></div></Section><Section title="Bots"><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{bots.map(r=><div key={r.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div><div className="font-medium">{r.username}</div><div className="text-xs text-muted-foreground">{r.full_name??'—'} · {r.points.toLocaleString?.()??r.points}</div></div><StatusBadge status={r.is_active?'ACTIVE':'DISABLED'} dense/></div><div className="mt-2 flex justify-end gap-1"><Button variant="ghost" size="sm" onClick={()=>edit(r)}>Edit</Button><Button variant="ghost" size="sm" onClick={()=>void del(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div></div>)}</div></Section></div>
}
